return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'de_AT','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:50:40+00:00','po-revision-date'=>'2026-11-05T19:50:40+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Ergänzt fehlende Übersetzungen für die auf deiner Website bereits installierten Plugins und Themes.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Dieser Upload-Bildschirm war veraltet: Inzwischen wurde ein anderer Upload vorbereitet. Es wurde nichts gesendet. Überprüfe den aktuellen in der Übersetzungsliste.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Der kostenlose Service-Tarif bietet jeder Website eine begrenzte Anzahl an Slots für Plugins und Themes; die belegten Slots werden nach der Aktivierung von Babilim unter Einstellungen angezeigt.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Wenn du eine Übersetzung anforderst, wird diesem Plugin bzw. Theme einer der Slots des kostenlosen Service-Tarifs für diese Website zugewiesen (das Limit beträgt %1$d für Themes und %2$d für Plugins), sofern es nicht bereits einen belegt. Ein Slot bleibt belegt und wird auch durch eine fehlgeschlagene Übersetzung nicht freigegeben.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Wenn du eine Übersetzung anforderst, wird diesem Plugin bzw. Theme einer der Slots des kostenlosen Service-Tarifs für diese Website zugewiesen, sofern es nicht bereits einen belegt. Ein Slot bleibt belegt und wird auch durch eine fehlgeschlagene Übersetzung nicht freigegeben.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Falls dieses Plugin bzw. Theme noch keinen der Slots des kostenlosen Service-Tarifs für diese Website belegt, wird ihm durch die Anforderung einer Übersetzung ein Slot zugewiesen (das Limit beträgt %1$d für Themes und %2$d für Plugins). Ein Slot bleibt belegt und wird auch durch eine fehlgeschlagene Übersetzung nicht freigegeben. Fortfahren?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Falls dieses Plugin bzw. Theme noch keinen der Slots des kostenlosen Service-Tarifs für diese Website belegt, wird ihm durch die Anforderung einer Übersetzung ein Slot zugewiesen. Ein Slot bleibt belegt und wird auch durch eine fehlgeschlagene Übersetzung nicht freigegeben. Fortfahren?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d Website in diesem Netzwerk ist so eingestellt, dass ihre Babilim-Identität beim Löschen des Plugins gelöscht wird. Die dieser Website zugeordnete kostenpflichtige Lizenz könnte dann nicht automatisch wiederhergestellt werden; Sie müssten sich an den Babilim-Support unter %2$s wenden. Um die Identität zu behalten, klicken Sie auf „Abbrechen“, deaktivieren Sie in den Babilim-Einstellungen dieser Website die Option „Beim Deinstallieren alle Babilim-Daten löschen“ und deaktivieren Sie das Plugin erneut. Trotzdem deaktivieren?' . "\0" . '%1$d Websites in diesem Netzwerk sind so eingestellt, dass ihre Babilim-Identität beim Löschen des Plugins gelöscht wird. Die diesen Websites zugeordnete kostenpflichtige Lizenz könnte dann nicht automatisch wiederhergestellt werden; Sie müssten sich an den Babilim-Support unter %2$s wenden. Um die Identitäten zu behalten, klicken Sie auf „Abbrechen“, deaktivieren Sie in den Babilim-Einstellungen jeder Website die Option „Beim Deinstallieren alle Babilim-Daten löschen“ und deaktivieren Sie das Plugin erneut. Trotzdem deaktivieren?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s nichts zu tun.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Wähle die Sprache aus.','%d failed'=>'%d fehlgeschlagen' . "\0" . '%d fehlgeschlagen','%d not yet tried'=>'%d noch nicht versucht' . "\0" . '%d noch nicht versucht','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d Bericht wartet. „Immer teilen“ und „Nicht teilen“ gelten für alle.' . "\0" . '%d Berichte warten. „Immer teilen“ und „Nicht teilen“ gelten für alle.','%d skipped'=>'%d übersprungen' . "\0" . '%d übersprungen','%d succeeded'=>'%d erfolgreich' . "\0" . '%d erfolgreich','%d to install'=>'%d zur Installation' . "\0" . '%d zur Installation','(a public key generated for this site)'=>'(ein für diese Website erzeugter öffentlicher Schlüssel)','(detected)'=>'(erkannt)','(generic codes and coordinates only)'=>'(nur allgemeine Codes und Koordinaten)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Eine Bereinigung wurde am %1$s angehalten: %2$s. Es wurde nichts gelöscht.','A file in the component could not be read, so it was not packaged.'=>'Eine Datei in der Komponente konnte nicht gelesen werden und wurde daher nicht gepackt.','A host that serves only one PHP request at a time cannot complete this step.'=>'Ein Host, der nur eine PHP-Anfrage gleichzeitig verarbeitet, kann diesen Schritt nicht abschließen.','A part of the upload kept failing, so the upload was cancelled.'=>'Ein Teil des Uploads schlug wiederholt fehl, daher wurde der Upload abgebrochen.','A translation cannot be requested for that locale on this site right now.'=>'Für dieses Gebietsschema kann auf dieser Website derzeit keine Übersetzung angefordert werden.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Ein Schreibvorgang im Übersetzungsindex stand am %1$s (%2$s) im Konflikt mit einer anderen Anfrage und wurde nicht angewendet; die neueste Version wurde beibehalten.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Ein Schreibvorgang im Übersetzungsindex am %1$s (%2$s) konnte nicht abgeschlossen werden und wurde nicht angewendet (%3$s).','Account'=>'Konto','Add another language'=>'Weitere Sprache hinzufügen','Advanced'=>'Erweitert','All'=>'Alle','All free-plan slots for this site are used'=>'Alle Plätze im kostenlosen Paket für diese Website sind belegt','All languages'=>'Alle Sprachen','Already in WordPress core'=>'Bereits im WordPress-Kern enthalten','Already installed.'=>'Bereits installiert.','Always share'=>'Immer teilen','Another installation is running; try again in a moment.'=>'Eine andere Installation läuft gerade; versuche es gleich noch einmal.','Automatic installs'=>'Automatische Installationen','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Automatische Installationen sind jetzt deaktiviert; aktivieren Sie sie in den Einstellungen wieder, wenn Sie möchten.','Available'=>'Verfügbar','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Verfügbare Übersetzungen können mit einem Klick installiert und fehlende angefordert werden. Solange automatische Installationen aktiviert sind, werden Übersetzungen, die der Dienst für die von dir verwalteten Sprachen als verfügbar auflistet, bei der zweimal täglich stattfindenden Synchronisierung installiert.','Available · %s'=>'Verfügbar · %s','Babilim Settings'=>'Babilim-Einstellungen','Babilim adds translations for every language checked here.'=>'Babilim fügt Übersetzungen für jede hier ausgewählte Sprache hinzu.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim konnte keinen temporären Ordner außerhalb der Website bestätigen, daher wurde die Komponente nicht gepackt und nichts hochgeladen. Definiere BABILIM_TEMP_DIR in wp-config.php als beschreibbaren Ordner außerhalb des Web-Stammverzeichnisses (zum Beispiel ein Ordner neben, nicht innerhalb, des öffentlichen Verzeichnisses deiner Website) oder frage deinen Hoster nach einem solchen Ordner.','Babilim could not finish checking this site.'=>'Babilim konnte die Prüfung dieser Website nicht abschließen.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim konnte die Aktivierung nicht abschließen (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim konnte die Überprüfung dieser Website nicht abschließen (der Dienst konnte die Website beim Rückruf nicht erreichen). Die Registrierung ist pausiert.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim konnte diese Website nicht verifizieren. Daher wird nichts heruntergeladen oder installiert, bis die Verifizierung erfolgreich ist.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim konnte diese Website nicht verifizieren, daher wird nichts heruntergeladen oder installiert.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim findet die Plugins und Themes dieser Website, für die es keine Übersetzung in Ihrer Sprache gibt, und installiert für jedes eine.','Babilim has not been enabled for this site yet.'=>'Babilim wurde für diese Website noch nicht aktiviert.','Babilim has not installed any translation for this language.'=>'Babilim hat für diese Sprache keine Übersetzung installiert.','Babilim hit an error. Share an error report?'=>'Bei Babilim ist ein Fehler aufgetreten. Fehlerbericht teilen?','Babilim installed %d translation automatically since your last visit.'=>'Babilim hat seit Ihrem letzten Besuch %d Übersetzung automatisch installiert.' . "\0" . 'Babilim hat seit Ihrem letzten Besuch %d Übersetzungen automatisch installiert.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim ist deaktiviert. Es wird nichts mehr gesendet; bereits installierte Übersetzungen funktionieren weiterhin.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim ist aktiviert: Diese Website ist verifiziert und %d Komponente wurde gefunden.' . "\0" . 'Babilim ist aktiviert: Diese Website ist verifiziert und %d Komponenten wurden gefunden.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim wird aktiviert und prüft diese Website … (letzter Versuch: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim wird aktiviert und prüft diese Website … Laden Sie diese Seite neu oder warten Sie, bis die geplante Prüfung abgeschlossen ist.','Babilim is not enabled.'=>'Babilim ist nicht aktiviert.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim ist so eingestellt, dass die Identität dieser Website beim Löschen des Plugins gelöscht wird. Die dieser Website zugeordnete kostenpflichtige Lizenz könnte dann nicht automatisch wiederhergestellt werden; Sie müssten sich an den Babilim-Support unter %s wenden. Um die Identität zu behalten, klicken Sie auf „Abbrechen“, deaktivieren Sie in den Babilim-Einstellungen die Option „Beim Deinstallieren alle Babilim-Daten löschen“ und deaktivieren Sie das Plugin erneut. Trotzdem deaktivieren?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim hat für diesen Schritt die Zeitgrenze erreicht und setzt ihn bei der nächsten Prüfung fort.','Babilim settings'=>'Babilim-Einstellungen','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Die Babilim-Synchronisierung wird vom Dienst vorübergehend verzögert (Ratenbegrenzung); sie versucht es nach %s erneut.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim wurde aktualisiert, während dieser Upload wartete. Das alte Paket wurde verworfen; bitte bestätige den Upload erneut.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim lädt diese Dateien von %1$s (Version %2$s) hoch: jede .php- und .js-Datei, jede block.json-Datei sowie die Dateien readme.txt, readme.md, style.css und theme.json in ihrem Hauptordner. Sie dienen dazu, die zu übersetzenden Texte zu finden und das Plugin bzw. Theme zu identifizieren.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest ist nicht verfügbar: %s','Back'=>'Zurück','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Hast du für diese Domain bereits eine Lizenz erworben? Gib den Wiederherstellungscode ein, den du beim Checkout erhalten hast.','Broken placeholder'=>'Fehlerhafter Platzhalter','Build'=>'Build','Built'=>'Erstellt','Bulk actions apply only to the selected language of each selected component.'=>'Massenaktionen gelten nur für die ausgewählte Sprache jeder ausgewählten Komponente.','Bulk actions apply to every matching language of each selected component.'=>'Massenaktionen gelten für jede passende Sprache jeder ausgewählten Komponente.','Bulk download:'=>'Massendownload:','Bulk request:'=>'Massenanfrage:','Bulk update:'=>'Massenaktualisierung:','Bundled with the plugin'=>'Im Plugin enthalten','Bundled with the theme'=>'Im Theme enthalten','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Mit einem Klick auf „Aktivieren“ stimmen Sie zu, die oben aufgeführten Informationen an Babilim zu senden.','By continuing you confirm that you have the right to upload this component.'=>'Wenn du fortfährst, bestätigst du, dass du berechtigt bist, diese Komponente hochzuladen.','Cancel'=>'Abbrechen','Category'=>'Kategorie','Check again'=>'Erneut prüfen','Check again now'=>'Jetzt erneut prüfen','Checkout is not available for this site right now.'=>'Der Checkout ist für diese Website derzeit nicht verfügbar.','Choose'=>'Auswählen','Choose a category…'=>'Kategorie auswählen …','Choose a language'=>'Sprache auswählen','Choose a language…'=>'Sprache auswählen …','Clear filters'=>'Filter zurücksetzen','Close'=>'Schließen','Component'=>'Komponente','Confirm'=>'Bestätigen','Conflicting keys'=>'Konfliktierende Schlüssel','Continue'=>'Fortsetzen','Continue next batch (%d left)'=>'Nächsten Stapel fortsetzen (noch %d)','Continuing…'=>'Wird fortgesetzt …','Could not back up %s before replacing it.'=>'%s konnte vor dem Ersetzen nicht gesichert werden.','Could not create the package archive.'=>'Das Paketarchiv konnte nicht erstellt werden.','Could not determine active components; the existing merged index was left unchanged.'=>'Aktive Komponenten konnten nicht ermittelt werden; der bestehende zusammengeführte Index wurde nicht verändert.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Installierte Plugins und Themes konnten nicht ermittelt werden; die Bereinigung wurde übersprungen, es wurde nichts gelöscht.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Die vollständige Liste der WordPress.org-Gebietsschemas konnte vom Dienst nicht geladen werden, daher kann derzeit keine weitere Sprache hinzugefügt werden.','Could not move %s into place.'=>'%s konnte nicht an die richtige Stelle verschoben werden.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Der zusammengeführte Index für „%s“ konnte nicht an seinen Platz verschoben werden; der bisher ausgelieferte Index (falls vorhanden) wurde entfernt, statt halb aktualisiert zu bleiben. Bis zum nächsten erfolgreichen Neuaufbau wird für diese Sprache keine Ergänzung zur Standarddomäne ausgeliefert.','Could not open zip: %s'=>'Zip-Datei konnte nicht geöffnet werden: %s','Could not prepare %s for rollback.'=>'%s konnte nicht für den Rollback vorbereitet werden.','Could not read %s back after moving it into place.'=>'%s konnte nach dem Verschieben an den Zielort nicht erneut gelesen werden.','Could not read: %s'=>'Konnte nicht gelesen werden: %s','Could not restore the purchase: %s'=>'Der Kauf konnte nicht wiederhergestellt werden: %s','Could not show a new restore code: %s'=>'Ein neuer Wiederherstellungscode konnte nicht angezeigt werden: %s','Could not stage %s'=>'%s konnte nicht bereitgestellt werden.','Could not stage default/%s'=>'default/%s konnte nicht bereitgestellt werden.','Could not start checkout: %s'=>'Der Checkout konnte nicht gestartet werden: %s','Could not verify entry count for %s'=>'Die Eintragsanzahl für %s konnte nicht überprüft werden.','Could not write the downloaded package to disk.'=>'Das heruntergeladene Paket konnte nicht auf die Festplatte geschrieben werden.','Could not write the staged merged index.'=>'Der bereitgestellte zusammengeführte Index konnte nicht geschrieben werden.','Current translation'=>'Aktuelle Übersetzung','Custom overrides'=>'Individuelle Überschreibungen','Danger zone'=>'Gefahrenbereich','Default supplement entry count mismatch.'=>'Abweichende Eintragsanzahl in der Standardergänzung.','Delete all Babilim data on uninstall'=>'Beim Deinstallieren alle Babilim-Daten löschen','Disable Babilim'=>'Babilim deaktivieren','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim deaktivieren? Installierte Übersetzungen bleiben erhalten, es werden aber keine weiteren Prüfungen oder Downloads ausgeführt.','Don\'t share'=>'Nicht teilen','Download'=>'Herunterladen','Downloaded and installed.'=>'Heruntergeladen und installiert.','Downloading…'=>'Wird heruntergeladen …','Downloads: %1$d/%2$d (%3$s)'=>'Downloads: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Der jeweilige Beitrag jeder Komponente zur gemeinsamen Ergänzung zur Standarddomäne jedes Gebietsschemas.','Enable Babilim'=>'Babilim aktivieren','Enabling…'=>'Wird aktiviert …','English (United States)'=>'Englisch (USA)','Entries'=>'Einträge','Entry count mismatch for %s'=>'Abweichende Eintragsanzahl bei %s','Error reports'=>'Fehlerberichte','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Jedes installierte Plugin und Theme: Slug, Version, Textdomäne(n), ob es ein Eintrag auf wp.org ist, die mitgelieferten eigenen Sprachen und für welche Sprachen du bereits eine Babilim-Übersetzung installiert hast.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Alle auf dieser Website verwendeten Sprachen (Website-Sprache, installierte Sprachpakete, Benutzersprachen und alle, die du manuell hinzufügst). Keine Sprache wird anders behandelt als eine andere.','Excluded'=>'Ausgeschlossen','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Dateien mit anderen Namen oder Endungen sind nicht enthalten, ebenso wenig die Ordner uploads, cache, logs, backup, data, vendor, node_modules und languages, versteckte Dateien oder Dateien, deren Namen gängigen geheimen Daten entsprechen (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Codedateien können dennoch Text oder Daten enthalten, die du nicht teilen möchtest; prüfe sie, wenn du unsicher bist. Der Dienst entfernt beim Eingang dieselben Arten von Dateien erneut.','Free'=>'Kostenlos','Free-plan slots'=>'Plätze im kostenlosen Paket','General'=>'Allgemein','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Wenn diese Option aktiviert ist, wird beim Deinstallieren auch die Identität dieser Website gelöscht. Die dieser Website zugeordnete kostenpflichtige Lizenz kann danach nicht automatisch wiederhergestellt werden; Sie müssten sich dazu an den Babilim-Support unter %s wenden.','Included'=>'Enthalten','Included in index'=>'Im Index enthalten','Install available translations automatically'=>'Verfügbare Übersetzungen automatisch installieren','Installed'=>'Installiert','Installed translations are kept, but no further checks or downloads will run.'=>'Installierte Übersetzungen bleiben erhalten, es werden jedoch keine weiteren Prüfungen oder Downloads mehr ausgeführt.','Installed · %s'=>'Installiert · %s','Installed · built for %1$s, this site has %2$s'=>'Installiert · erstellt für %1$s, diese Website hat %2$s','Installed · built for %s'=>'Installiert · erstellt für %s','Installed · built for %s, all free-plan slots for this site are used'=>'Installiert · erstellt für %s, alle Plätze im kostenlosen Paket für diese Website sind belegt','Installed · built for %s, new version failed'=>'Installiert · erstellt für %s, neue Version fehlgeschlagen','Installed · built for %s, new version not covered by the free service plan'=>'Installiert · erstellt für %s, neue Version nicht vom kostenlosen Servicepaket abgedeckt','Installed · built for %s, new version scheduled'=>'Installiert · erstellt für %s, neue Version geplant','Installed · built for %s, translating the new version…'=>'Installiert · erstellt für %s, die neue Version wird übersetzt …','Installed · built for a different version'=>'Installiert · für eine andere Version erstellt','Installed · built for a different version, all free-plan slots for this site are used'=>'Installiert · für eine andere Version erstellt, alle Plätze im kostenlosen Paket für diese Website sind belegt','Installed · built for a different version, new version failed'=>'Installiert · für eine andere Version erstellt, neue Version fehlgeschlagen','Installed · built for a different version, new version not covered by the free service plan'=>'Installiert · für eine andere Version erstellt, neue Version nicht vom kostenlosen Servicepaket abgedeckt','Installed · built for a different version, new version scheduled'=>'Installiert · für eine andere Version erstellt, neue Version geplant','Installed · built for a different version, translating the new version…'=>'Installiert · für eine andere Version erstellt, die neue Version wird übersetzt …','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Er wird vom Hosting-Anbieter des Dienstes gespeichert und von KI-Modellen verarbeitet, um die Übersetzung zu erstellen.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Meine eigenen Übersetzungsüberschreibungen beibehalten, wenn alles gelöscht oder dieses Plugin deinstalliert wird.','Language'=>'Sprache','Language:'=>'Sprache:','Languages'=>'Sprachen','Languages found on this site: %s.'=>'Auf dieser Website gefundene Sprachen: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Letzte Bereinigung am %1$s: %2$d neu markiert, %3$d Datei(en) gelöscht, %4$d Datensatz/Datensätze entfernt.','Maintenance'=>'Wartung','Maintenance status is not available right now.'=>'Der Wartungsstatus ist derzeit nicht verfügbar.','Manifest unavailable: %s'=>'Manifest nicht verfügbar: %s','Negation reversed'=>'Verneinung umgekehrt','No'=>'Nein','No build is available to download for this locale.'=>'Für dieses Gebietsschema steht kein Build zum Herunterladen zur Verfügung.','No cleanup has run yet.'=>'Es wurde noch keine Bereinigung ausgeführt.','No components match these filters. %s'=>'Keine Komponenten entsprechen diesen Filtern. %s','No components synced yet.'=>'Noch keine Komponenten synchronisiert.','No installed translation matches.'=>'Keine installierte Übersetzung stimmt überein.','No language is managed yet.'=>'Noch keine Sprache wird verwaltet.','No pending challenge for this nonce.'=>'Für diese Nonce ist keine Challenge ausstehend.','No pending challenge to verify.'=>'Es gibt keine ausstehende Herausforderung zur Verifizierung.','No plugins or themes found.'=>'Keine Plugins oder Themes gefunden.','No previous build to roll back to.'=>'Es gibt keinen früheren Build, auf den zurückgesetzt werden könnte.','No record for %s'=>'Kein Eintrag für %s','No site id is on file to rotate a token for.'=>'Es ist keine Website-ID hinterlegt, für die ein Token erneuert werden könnte.','No — component inactive'=>'Nein – Komponente inaktiv','No — component removed'=>'Nein – Komponente entfernt','No — installed version differs from the active one'=>'Nein – Die installierte Version weicht von der aktiven ab','Not a valid server_build_id: %s'=>'Keine gültige server_build_id: %s','Not covered by the free service plan'=>'Nicht vom kostenlosen Servicepaket abgedeckt','Not installed'=>'Nicht installiert','Not registered yet'=>'Noch nicht registriert','Not supported'=>'Nicht unterstützt','Not verified'=>'Nicht verifiziert','Note (optional)'=>'Anmerkung (optional)','Nothing to choose.'=>'Nichts zur Auswahl.','Nothing to confirm.'=>'Nichts zu bestätigen.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Standardmäßig deaktiviert: Beim Löschen des Plugins bleibt die Identität dieser Website erhalten, sodass sie bei einer Neuinstallation wiederverwendet werden kann.','One or more served files no longer match the manifest.'=>'Eine oder mehrere bereitgestellte Dateien stimmen nicht mehr mit dem Manifest überein.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Einmaliger Kauf für diese Website: %1$s %2$s. Enthält alle künftigen Übersetzungsupdates. Die Zahlung wird von Paddle in einem neuen Tab abgewickelt.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Dies kann nur ein Netzwerkadministrator tun, da dadurch Übersetzungsdateien geändert werden, die von allen Websites in diesem Netzwerk gemeinsam genutzt werden.','Only plugins and themes can be packaged.'=>'Nur Plugins und Themes können gepackt werden.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Nur wenn du einen Upload für ein Plugin oder Theme bestätigst, das nicht auf WordPress.org verfügbar ist: jede .php- und .js-Datei, jede block.json-Datei sowie die Dateien readme.txt, readme.md, style.css und theme.json im Hauptordner dieser Komponente, als Zip-Datei, nachdem Dateien, die gängigen geheimen Daten entsprechen, ausgelassen wurden.','Open Babilim settings'=>'Babilim-Einstellungen öffnen','Original language'=>'Originalsprache','Original string'=>'Originalzeichenfolge','Paid'=>'Kostenpflichtig','Partner'=>'Partner','Please check that your site can be reached from the internet, then try again.'=>'Bitte prüfen Sie, ob Ihre Website aus dem Internet erreichbar ist, und versuchen Sie es dann erneut.','Please choose a category for this report.'=>'Bitte wähle eine Kategorie für diese Meldung aus.','Plugin'=>'Plugin','Plugin · %s'=>'Plugin · %s','Plugins'=>'Plugins','Preview'=>'Vorschau','Purchase restored. This site is now licensed.'=>'Kauf wiederhergestellt. Diese Website ist jetzt lizenziert.','Re-parsed entry count did not match the built index.'=>'Die Anzahl der erneut geparsten Einträge stimmte nicht mit dem erstellten Index überein.','Re-verify'=>'Erneut verifizieren','Rebuild index now'=>'Index jetzt neu erstellen','Refusing to write outside the Babilim language-file directory.'=>'Das Schreiben außerhalb des Babilim-Sprachdateiverzeichnisses wird verweigert.','Registration response was missing required fields.'=>'In der Registrierungsantwort fehlten erforderliche Felder.','Registration restarted.'=>'Registrierung neu gestartet.','Remove'=>'Entfernen','Remove everything Babilim installed'=>'Alles von Babilim Installierte entfernen','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Alles von Babilim Installierte entfernen? Dadurch werden alle von Babilim installierten Sprachdateien für sämtliche Plugins und Themes auf dieser Website gelöscht.','Remove the %2$s translation of %1$s from this site?'=>'Die Übersetzung %2$s von %1$s von dieser Website entfernen?','Removed %d installed component.'=>'%d installierte Komponente entfernt.' . "\0" . '%d installierte Komponenten entfernt.','Removed after a failed integrity check'=>'Nach fehlgeschlagener Integritätsprüfung entfernt','Removed.'=>'Entfernt.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Entfernt alle von Babilim installierten Sprachdateien für sämtliche Plugins und Themes auf dieser Website.','Report a problem'=>'Problem melden','Report translation'=>'Übersetzung melden','Request newer translation'=>'Neuere Übersetzung anfordern','Request translation'=>'Übersetzung anfordern','Requestable'=>'Anforderbar','Requesting…'=>'Wird angefordert …','Restart registration'=>'Registrierung neu starten','Restore code'=>'Wiederherstellungscode','Restore purchase'=>'Kauf wiederherstellen','Retry request'=>'Anfrage wiederholen','Roll back'=>'Zurücksetzen','Roll back and report'=>'Zurücksetzen und melden','Roll back and send report'=>'Zurücksetzen und Bericht senden','Roll back the %2$s translation of %1$s to the previous build?'=>'Die Übersetzung für %1$s in der Sprache %2$s auf den vorherigen Build zurücksetzen?','Rolled back and reported.'=>'Zurückgesetzt und gemeldet.','Rolled back to the previous build.'=>'Auf den vorherigen Build zurückgesetzt.','Rolled back, but the report could not be sent: %s'=>'Zurückgesetzt, aber die Meldung konnte nicht gesendet werden: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Beim Zurücksetzen würde „%1$s“ (%2$s) überschrieben, das jetzt für eine andere installierte Komponente (%3$s) ausgeliefert wird; es wurde nichts geändert.','Rotate-token response was missing site_token.'=>'In der Antwort zur Token-Erneuerung fehlte site_token.','Save changes'=>'Änderungen speichern','Scheduled, waiting to be processed'=>'Geplant, wartet auf Verarbeitung','Search'=>'Suchen','Search components'=>'Komponenten durchsuchen','Search the installed translations'=>'Installierte Übersetzungen durchsuchen','Select all'=>'Alle auswählen','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Wähle weniger Komponenten aus: höchstens %1$d Vorgänge pro Durchlauf (du hast %2$d ausgewählt).','Send report'=>'Bericht senden','Service plan'=>'Servicepaket','Settings'=>'Einstellungen','Share error reports'=>'Fehlerberichte teilen','Share this report'=>'Diesen Bericht teilen','Show a new restore code'=>'Neuen Wiederherstellungscode anzeigen','Show the "Report translation" entry in the admin toolbar'=>'Den Eintrag „Report translation“ in der Symbolleiste des Admin-Bereichs anzeigen','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Ein Teil des Textes dieser Komponente ist vom Autor fest codiert und kann nicht durch ein Sprachpaket übersetzt werden.','Status'=>'Status','Status unknown'=>'Status unbekannt','String context'=>'String-Kontext','Suggested translation'=>'Übersetzungsvorschlag','Supplementary translation index'=>'Index der ergänzenden Übersetzungen','Supplementary translation index rebuilt.'=>'Ergänzender Übersetzungsindex neu aufgebaut.','Supplementary translation maintenance'=>'Wartung der ergänzenden Übersetzungen','Supplementary translations'=>'Ergänzende Übersetzungen','Sweep aborted without orphaning anything: %s.'=>'Bereinigung abgebrochen, ohne einen Eintrag als verwaist zu markieren: %s.','Sweep complete: %d file deleted.'=>'Durchlauf abgeschlossen: %d Datei gelöscht.' . "\0" . 'Durchlauf abgeschlossen: %d Dateien gelöscht.','Sweep now'=>'Jetzt durchsuchen','Sync complete.'=>'Synchronisierung abgeschlossen.','Thank you. Your report was sent.'=>'Danke! Deine Meldung wurde gesendet.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Diese Komponente ist auf dieser Website nicht installiert, daher kann dafür keine Übersetzung angefordert werden.','That does not look like a restore code.'=>'Das sieht nicht wie ein Wiederherstellungscode aus.','That is not a valid WordPress locale code. Nothing was saved.'=>'Das ist kein gültiger WordPress-Gebietsschemacode. Es wurde nichts gespeichert.','That is not a valid build identifier.'=>'Das ist keine gültige Build-Kennung.','The change could not be recorded in the translation index; please try again.'=>'Die Änderung konnte nicht im Übersetzungsindex erfasst werden. Bitte versuche es erneut.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Die Bereinigung wurde durchgeführt, aber einige ihrer Änderungen konnten nicht im Übersetzungsindex erfasst werden; die nächste Bereinigung versucht es erneut.','The component has no files that can be uploaded.'=>'Die Komponente enthält keine Dateien, die hochgeladen werden können.','The component is not inside the plugins or themes directory.'=>'Die Komponente befindet sich nicht im Plugin- oder Theme-Verzeichnis.','The component\'s main file was not found.'=>'Die Hauptdatei der Komponente wurde nicht gefunden.','The download response was missing a usable location.'=>'In der Download-Antwort fehlte ein verwendbarer Speicherort.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Der Eintrag öffnet ein Panel, in dem du die von Babilim auf dieser Website installierten Übersetzungen durchsuchen und eine davon melden kannst.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Das Feld „%1$s“ ist zu lang: Es hat %2$d Zeichen, das Limit beträgt %3$d. Es wurde nichts gesendet; bitte kürze den Text und versuche es erneut.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Die angegebene Domäne „%1$s“ stimmt weder mit dem eigenen Slug „%2$s“ des Paketmanifests noch mit seiner text_domain „%3$s“ überein.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Der zusammengeführte Index für „%s“ wurde neu erstellt, aber der Übersetzungsindex konnte ihn nicht erfassen; der nächste Neuaufbau versucht es erneut.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Der Originaltext und die daraus erstellten Übersetzungen werden anderen Websites bereitgestellt, die dieselbe Version installieren.','The package declares no main translation file.'=>'Das Paket deklariert keine Haupt-Übersetzungsdatei.','The package has no %s for its own text domain.'=>'Das Paket enthält keine %s für seine eigene Textdomäne.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Die Art „%1$s“ des Paketmanifests stimmt nicht mit der angeforderten Art „%2$s“ überein.','The package produced no servable main translation file.'=>'Das Paket hat keine auslieferbare Haupt-Übersetzungsdatei erzeugt.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Die Textdomäne „%1$s“ des Pakets stimmt nicht mit der Kopie der Komponente auf dieser Website („%2$s“) überein. Daher wurde das Paket nicht installiert.','The packaged component could not be read.'=>'Die gepackte Komponente konnte nicht gelesen werden.','The registration challenge is not in the expected form.'=>'Die Registrierungsabfrage hat nicht das erwartete Format.','The report could not be sent.'=>'Der Bericht konnte nicht gesendet werden.','The search could not be completed.'=>'Die Suche konnte nicht abgeschlossen werden.','The service asked this site to wait before syncing again.'=>'Der Dienst hat diese Website aufgefordert, vor der nächsten Synchronisierung zu warten.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Der Dienst konnte Ihre Website nicht erreichen. Wahrscheinlich blockiert eine Firewall, ein Sicherheits-Plugin oder eine Hosting-Regel die Anfrage; bitte erlauben Sie Anfragen an /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Das Upload-Angebot des Dienstes war unvollständig.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Die Textdomäne „%1$s“ (%2$s) wird bereits für eine andere installierte Komponente bereitgestellt (%3$s); es wurde nichts installiert.','The upload is kept until you ask Babilim to delete it.'=>'Der Upload wird gespeichert, bis du Babilim aufforderst, ihn zu löschen.','Theme'=>'Theme','Theme · %s'=>'Theme · %s','Themes'=>'Themes','There is no upload in progress.'=>'Es läuft derzeit kein Upload.','There is no upload waiting for confirmation.'=>'Es wartet kein Upload auf Bestätigung.','These are the languages this site uses. You can change them in %s.'=>'Das sind die Sprachen, die diese Website verwendet. Du kannst sie unter %s ändern.','These fields will be sent:'=>'Diese Felder werden gesendet:','This build is not one this site currently knows about for this component/locale.'=>'Dieser Build ist dieser Website für diese Komponente/dieses Gebietsschema derzeit nicht bekannt.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Diese Komponente gibt keine Versionsnummer an, daher kann dafür keine Übersetzung angefordert werden.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Diese Komponente ist größer, als der Dienst akzeptiert, und kann daher nicht hochgeladen werden.','This component was already uploaded. Babilim is checking it now.'=>'Diese Komponente wurde bereits hochgeladen. Babilim prüft sie gerade.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Die Versionsnummer dieser Komponente ist länger als %d Zeichen. Das kann Babilim nicht verarbeiten, daher kann dafür keine Übersetzung angefordert werden.','This issues a new restore code and the previous one stops working. Continue?'=>'Dadurch wird ein neuer Wiederherstellungscode ausgestellt und der bisherige funktioniert nicht mehr. Fortfahren?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Dieses Netzwerk hat zu viele Websites, um sie einzeln zu prüfen, und einige davon sind möglicherweise so eingestellt, dass ihre Babilim-Identität beim Löschen des Plugins gelöscht wird. Die einer solchen Website zugeordnete kostenpflichtige Lizenz könnte dann nicht automatisch wiederhergestellt werden; Sie müssten sich an den Babilim-Support unter %s wenden. Um die Identitäten zu behalten, klicken Sie auf „Abbrechen“, deaktivieren Sie in den Babilim-Einstellungen jeder Website die Option „Beim Deinstallieren alle Babilim-Daten löschen“ und deaktivieren Sie das Plugin erneut. Trotzdem deaktivieren?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Die Version dieses Plugins, damit der Dienst dir mitteilen kann, dass ein Update nötig ist, wenn sie zu alt ist, um mit ihm zu kommunizieren.','This report does not name a valid plugin or theme and locale.'=>'Diese Meldung benennt kein gültiges Plugin oder Theme und kein gültiges Gebietsschema.','This report does not name an installed string.'=>'Dieser Bericht nennt keinen installierten String.','This report is missing a valid build to report against.'=>'Dieser Meldung fehlt ein gültiger Build, auf den sie sich beziehen kann.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Dieser Bericht wird öffentlich auf GitHub veröffentlicht und kann von Dritten gespeichert werden.','This restore code was not recognised for this site.'=>'Dieser Wiederherstellungscode wurde für diese Website nicht erkannt.','This site already has an active registration that can no longer be recovered automatically.'=>'Diese Website hat bereits eine aktive Registrierung, die nicht mehr automatisch wiederhergestellt werden kann.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Diese Website hat %1$d Komponenten in %2$d Sprachen, wofür %3$d Prüfungsblöcke nötig sind; Babilim kann pro Durchlauf höchstens %4$d verarbeiten. Reduziere die verwalteten Sprachen unter „Einstellungen“ oder deaktiviere nicht benötigte Plugins und Themes und klicke dann auf „Erneut prüfen“.','This site has no purchase to show a code for.'=>'Für diese Website gibt es keinen Kauf, für den ein Code angezeigt werden könnte.','This site is already licensed. Reload the page.'=>'Diese Website ist bereits lizenziert. Lade die Seite neu.','This site is not registered with Babilim yet.'=>'Diese Website ist noch nicht bei Babilim registriert.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Diese Website überschreitet die Größe, die der Dienst in einer Synchronisierung akzeptiert, daher wurden einige Elemente ausgelassen: %1$d Komponenten und %2$d Sprachen.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Diese Website ist Teil eines Multisite-Netzwerks, in dem neue Übersetzungen nicht automatisch installiert werden. Bereits installierte Übersetzungen werden weiterhin aktualisiert.','This site is verified.'=>'Diese Website ist verifiziert.','This site must be verified first.'=>'Diese Website muss zuerst verifiziert werden.','This site\'s URL, so the service can verify you own it.'=>'Die URL dieser Website, damit der Dienst überprüfen kann, dass sie dir gehört.','This site\'s address is too long for Babilim to register.'=>'Die Adresse dieser Website ist zu lang, als dass Babilim sie registrieren könnte.','This site\'s configured locale.'=>'Die konfigurierte Sprache dieser Website.','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Der öffentliche Installationsschlüssel dieser Website, mit dem nachgewiesen wird, dass Anfragen tatsächlich von dieser Website stammen. Es wird nur der öffentliche Teil gesendet.','This site\'s locale code is not one Babilim can register.'=>'Der Gebietsschemacode dieser Website kann von Babilim nicht registriert werden.','This string can\'t be reported from this site.'=>'Dieser String kann von dieser Website aus nicht gemeldet werden.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Dieser String gehört nicht zu den auf dieser Website installierten Übersetzungen. Suche erneut und wähle ihn aus der Liste aus.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Diese Übersetzung wurde seit deiner Suche aktualisiert. Suche erneut und wähle den String aus der neuen Liste aus.','To translate this component, Babilim needs its source.'=>'Um diese Komponente zu übersetzen, benötigt Babilim ihren Quellcode.','Too many attempts. Try again tomorrow.'=>'Zu viele Versuche. Versuchen Sie es morgen erneut.','Too many reports today. Try again tomorrow.'=>'Heute zu viele Berichte. Versuche es morgen erneut.','Too many requests.'=>'Zu viele Anfragen.','Toolbar'=>'Symbolleiste','Translating…'=>'Wird übersetzt …','Translation does not load'=>'Übersetzung wird nicht geladen','Translation failed'=>'Übersetzung fehlgeschlagen','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Übersetzungsdateien, die du in %s ablegst, haben immer Vorrang vor denen von Babilim. Sie bleiben erhalten, solange du dieses Häkchen nicht entfernst.','Translation requested.'=>'Übersetzung angefordert.','Translations'=>'Übersetzungen','Type'=>'Typ','Type at least 2 characters to search.'=>'Gib mindestens 2 Zeichen ein, um zu suchen.','Unexpected HTTP %d response.'=>'Unerwartete HTTP-Antwort %d.','Uninstall'=>'Deinstallation','Unknown kind: %s'=>'Unbekannte Art: %s','Unsafe domain: %s'=>'Unsichere Domain: %s','Unsafe locale: %s'=>'Unsichere Sprache: %s','Unsafe slug: %s'=>'Unsicherer Slug: %s','Unsafe text_domain: %s'=>'Unsichere text_domain: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Bis zu 20 ausstehende Diagnoseereignisse (z. B. eine Datei, die die Integritätsprüfung nicht bestanden hat), jeweils nur mit Code, Komponente und Sprache, niemals mit Zeichenfolgeninhalt oder übersetztem Text.','Update'=>'Aktualisieren','Update available'=>'Update verfügbar','Updates'=>'Updates','Updating…'=>'Wird aktualisiert …','Upgrade this site'=>'Diese Website upgraden','Upload and request'=>'Hochladen und anfordern','Upload cancelled.'=>'Upload abgebrochen.','Upload complete — translation requested.'=>'Upload abgeschlossen – Übersetzung angefordert.','Upload expired before it finished'=>'Upload ist abgelaufen, bevor er abgeschlossen wurde','Upload in progress — continue or cancel'=>'Upload läuft – fortsetzen oder abbrechen','Upload this component?'=>'Diese Komponente hochladen?','Upload was not accepted'=>'Upload wurde nicht akzeptiert','Uploading'=>'Wird hochgeladen','Uploading part %1$d of %2$d…'=>'Teil %1$d von %2$d wird hochgeladen…','Uploading…'=>'Wird hochgeladen…','Verified'=>'Verifiziert','Verify response was missing site_token.'=>'In der Verifizierungsantwort fehlte site_token.','Version %s'=>'Version %s','What is sent when Babilim checks this site'=>'Was gesendet wird, wenn Babilim diese Website prüft','What is sent when you enable Babilim'=>'Was beim Aktivieren von Babilim gesendet wird','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Wenn in Babilim etwas fehlschlägt, wird ein Fehlerbericht an den Babilim-Dienst gesendet, damit er als öffentliches Issue auf GitHub veröffentlicht werden kann. Der Bericht wird im Namen dieser Website gesendet, mit derselben Authentifizierung wie jede andere Anfrage an den Babilim-Dienst. Der Dienst veröffentlicht nur den Fehlercode und die Versionen als öffentliches Issue auf GitHub; das öffentliche Issue enthält keine Website-Adresse, keine Inhalte und keine Dateipfade. Standardmäßig deaktiviert.','Where you saw this (optional)'=>'Wo du das gesehen hast (optional)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Solange diese Option aktiviert ist, werden Übersetzungen, die der Dienst für die von dir verwalteten Sprachen als verfügbar auflistet, bei der zweimal täglich stattfindenden Synchronisierung installiert.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Für diesen Kontext falsch','Wrong meaning'=>'Falsche Bedeutung','Wrong plural form'=>'Falsche Pluralform','Wrong term'=>'Falscher Begriff','Yes'=>'Ja','You are not allowed to do this.'=>'Du bist nicht berechtigt, dies zu tun.','Your PHP version, for compatibility.'=>'Deine PHP-Version, zur Kompatibilitätsprüfung.','Your WordPress version, to serve compatible translation files.'=>'Deine WordPress-Version, um kompatible Übersetzungsdateien bereitzustellen.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Dein neuer Wiederherstellungscode: %s. Bewahre ihn an einem sicheren Ort auf – der bisherige Code funktioniert nicht mehr.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Dein Bericht wird automatisch von AI-Modellen verarbeitet und kann diese Übersetzung für andere Websites verbessern.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Ihre Website hat geantwortet, aber nicht mit der erwarteten Antwort. Die REST-API wird möglicherweise von einem anderen Plugin umgeschrieben oder dieser Endpunkt wird zwischengespeichert; bitte schließen Sie /wp-json/babilim/v1/challenge vom Caching und Umschreiben aus.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Ihre Website hat zu lange für die Antwort gebraucht. Bitte versuchen Sie es später erneut und prüfen Sie, ob Ihr Hosting nicht zu langsam oder überlastet ist.','Zip has no manifest.json.'=>'Die ZIP-Datei enthält keine manifest.json.','Zip is missing expected default file: %s'=>'In der ZIP-Datei fehlt die erwartete Standarddatei: %s','Zip is missing expected file: %s'=>'In der ZIP-Datei fehlt die erwartete Datei: %s','_manifest.json has an unexpected structure'=>'_manifest.json hat eine unerwartete Struktur','could not read _manifest.json: %s'=>'_manifest.json konnte nicht gelesen werden: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest fehlt oder enthält ein ungültiges Feld „%s“.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'„server_build_id“ in expected_manifest ist keine gültige Build-ID.','failed to parse _manifest.json: %s'=>'_manifest.json konnte nicht geparst werden: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'es würde %1$d von %2$d verwalteten Komponenten als verwaist markieren (mehr als die Hälfte)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'es würde jede verwaltete %1$s-Komponente als verwaist markieren (%2$d von %2$d)','l10n.php entry count mismatch for %s'=>'Abweichende Anzahl der Einträge in l10n.php bei %s','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json enthält ein ungültiges Feld „default_domain_entries“.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json enthält ein ungültiges Feld „default_domain_files“.','manifest.json in the zip is not valid JSON.'=>'manifest.json in der ZIP-Datei ist kein gültiges JSON.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json enthält kein oder ein ungültiges „%s“.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json fehlt oder enthält ein ungültiges Feld „build_no“.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json fehlt oder enthält ungültige „entries“.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json fehlt oder enthält ein ungültiges Feld „extra_domains“.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json fehlt oder enthält ein ungültiges Feld „files“.','manifest.json\'s \'%s\' does not match the expected value.'=>'„%s“ in manifest.json stimmt nicht mit dem erwarteten Wert überein.','manifest.json\'s \'contract\' is not a valid version string.'=>'„contract“ in manifest.json ist keine gültige Versionszeichenfolge.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'„kind“ in manifest.json muss „plugin“ oder „theme“ sein.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'„server_build_id“ in manifest.json ist keine gültige Build-ID.','manifest.json\'s \'status\' must be \'published\'.'=>'Der Wert „status“ in manifest.json muss „published“ lauten.','nonce must be a hexadecimal string.'=>'Die Nonce muss eine hexadezimale Zeichenfolge sein.','per day'=>'pro Tag','rc_…'=>'rc_…','sha256 mismatch for %s'=>'SHA-256-Abweichung bei %s','sha256 mismatch for default/%s'=>'SHA-256-Abweichung bei default/%s','component kind in the sweep brake messageplugin'=>'Plugin','component kind in the sweep brake messagetheme'=>'Theme','problem report categoryOther'=>'Sonstiges','translation statusAvailable'=>'Verfügbar','translation statusInstalled'=>'Installiert']];